 ('信任但要验证：比较记录系统与派生数据（第 1 课的物化视图）的校验和。','CREATE MATERIALIZED VIEW IF NOT EXISTS monthly AS SELECT date_trunc(\'month\', created_at) m, count(*) n, sum(amount) total FROM orders GROUP BY 1;\nSELECT (SELECT sum(amount) FROM orders) = (SELECT sum(total) FROM monthly) AS consistent;',' consistent\n------------\n t'),
